{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "network_loss",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT CASE WHEN duration > 20000000000 THEN 'stalled_over_20s' ELSE 'normal' END AS bucket, count(*) AS n, round(quantile_cont(duration,0.5)/1e6,1) AS p50_ms, round(max(duration)/1e6,1) AS max_ms FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name='POST' AND attr_span_kind='Client' GROUP BY 1 ORDER BY 1",
          "claim": "About 8 of 54 seat POST client calls stall for 64-131 s while the median stays about 6 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT count(*) AS stalled_calls, sum(CASE WHEN s.span_id IS NULL THEN 1 ELSE 0 END) AS no_callee_span FROM abnormal_traces c LEFT JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id AND s.service_name <> 'ts-seat-service' WHERE c.service_name='ts-seat-service' AND c.span_name='POST' AND c.attr_span_kind='Client' AND c.duration > 20000000000",
          "claim": "Stalled seat POST calls have no child span in any downstream service, so the request never reached its callee.",
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name='POST' AND attr_span_kind='Client' AND duration > 20000000000 GROUP BY ALL",
          "claim": "Stalled seat POSTs fail with no HTTP status code, i.e. a transport-level timeout rather than an HTTP reply."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM normal_traces WHERE service_name='ts-seat-service' AND span_name='POST' AND attr_span_kind='Client' GROUP BY 1,2,3",
          "claim": "In the normal period seat's POST client calls had a p95 of about 13 ms, with no stalls."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-seat-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) callee_p95_ms, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name <> c.service_name GROUP BY 1,2 ORDER BY 1,2",
          "claim": "ts-travel-service's calls to ts-seat-service take about 130 s and return errors (6 of 8)."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) callee_p95_ms, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name <> c.service_name GROUP BY 1,2 ORDER BY 1,2",
          "claim": "ts-route-plan-service's calls to ts-travel-service reach 130 s p95 with 3 errors."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(c.duration,0.95)/1e6,1) callee_p95_ms, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name <> c.service_name GROUP BY 1,2 ORDER BY 1,2",
          "claim": "ts-travel-plan-service's calls to ts-route-plan-service reach 130 s p95 with 3 errors."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-travel-service','ts-ui-dashboard') AND attr_span_kind='Server' GROUP BY 1,2 ORDER BY 1,2",
          "claim": "Travel server spans show 500 errors after 130 s, and the dashboard's latency grows with them."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name = 'ts-travel-plan-service' AND attr_span_kind='Server' GROUP BY 1,2,3",
          "claim": "ts-travel-plan-service server latency reaches about 130 s p95 under the abnormal period."
        }
      ]
    }
  ]
}
